def shingles(t, n=3):
    w = t.lower().split()
    return {tuple(w[i:i + n]) for i in range(max(len(w) - n + 1, 1))}

def sim(a, b):
    return len(a & b) / max(len(a | b), 1)

def pack(passages, relevance, budget=6000, lam=0.7, margin=0.10):
    cap = int(budget * (1 - margin))
    sh = {p.uri: shingles(p.text) for p in passages}
    rest, chosen, used, left = list(passages), [], 0, []
    while rest:
        def score(p):
            red = max((sim(sh[p.uri], sh[c.uri]) for c in chosen), default=0.0)
            return lam * relevance[p.uri] - (1 - lam) * red
        best = max(rest, key=lambda p: (score(p), p.uri))
        rest.remove(best)
        n = count_tokens(best.text)
        if used + n > cap:
            left.append({'uri': best.uri, 'reason': 'over_budget'})
            continue
        chosen.append(best)
        used += n
    # tricky part: best at the edges, weakest in the middle (lost in the middle)
    front, back = [], []
    for i, p in enumerate(chosen):
        (front if i % 2 == 0 else back).append(p)
    ordered = front + back[::-1]
    items = [PackedItem(f'c{i + 1}', p.uri, p.text, count_tokens(p.text))
             for i, p in enumerate(ordered)]
    return PackResult(items, left)

