import re
from rapidfuzz import fuzz

NUM = re.compile(r'\d[\d,]*\.?\d*')
CAP = re.compile(r'\b[A-Z][a-zA-Z0-9]{2,}\b')

def supported(cl, passages):
    texts = [passages.get(c) for c in cl.cite_ids]
    if any(t is None for t in texts):
        return 'bad_cite_id'
    joined = ' '.join(texts)
    q = ' '.join(cl.evidence_quote.split())
    if fuzz.partial_ratio(q.lower(), ' '.join(joined.split()).lower()) < 90:
        return 'quote_not_found'
    src = q + ' ' + joined
    # tricky part: numbers compared without commas so 1,200 matches 1200
    have = {n.replace(',', '') for n in NUM.findall(src)}
    if any(n.replace(',', '') not in have for n in NUM.findall(cl.span)):
        return 'number_mismatch'
    if any(w not in src for w in CAP.findall(cl.span)):
        return 'name_mismatch'
    return None

def verify(draft, passages):
    kept, dropped, total = [], [], 0
    for b in draft.blocks:
        ok = []
        for cl in b.claims:
            total += 1
            why = supported(cl, passages)
            (dropped.append({'span': cl.span, 'reason': why}) if why else ok.append(cl))
        if ok:
            kept.append(b.model_copy(update={'claims': ok}))
    abstain = draft.abstain or (total > 0 and len(dropped) / total > 0.5)
    return Verified(kept, dropped, abstain)

