def label(ps, links):
    out = []
    for p in ps:
        newer = links.superseded_by(p.id)
        status = "superseded" if newer else "current"
        if links.contradicts(p.id) and not newer:
            status = "contradicted"
        out.append(Labelled(p, status))
    return sorted(out, key=lambda x: (x.status != "current", -x.p.version))
